import{_ as e,c as a,o as d,ag as o}from"./chunks/framework.DZ_cNctr.js";const m=JSON.parse('{"title":"Supported Formats","description":"Every format the viewer opens: OME-Zarr, OME-TIFF, CZI, Phenix and Yokogawa plates, and slides from Aperio, Hamamatsu, Leica, Philips, 3DHISTECH, Akoya, DICOM.","frontmatter":{"title":"Supported Formats","description":"Every format the viewer opens: OME-Zarr, OME-TIFF, CZI, Phenix and Yokogawa plates, and slides from Aperio, Hamamatsu, Leica, Philips, 3DHISTECH, Akoya, DICOM."},"headers":[],"relativePath":"guides/supported-formats.md","filePath":"guides/supported-formats.md"}'),r={name:"guides/supported-formats.md"};function i(s,t,l,n,h,p){return d(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="supported-formats" tabindex="-1">Supported Formats <a class="header-anchor" href="#supported-formats" aria-label="Permalink to &quot;Supported Formats&quot;">​</a></h1><p>Open the files your instruments write. OME-Zarr too. Here is what the viewer opens today. Nothing is converted or uploaded.</p><table tabindex="0"><thead><tr><th>Format</th><th>Kind</th><th>What you open</th><th>Views</th><th><a href="./local-files.html#zip-without-compression">Zip without compression</a></th></tr></thead><tbody><tr><td><a href="./ome-zarr.html">OME-Zarr</a></td><td>Microscopy</td><td>A folder, or its address</td><td>Images in 2D and 3D. Plates in Plate, Well and Field view</td><td>Yes, as one <code>.ozx</code> or <code>.zip</code> file</td></tr><tr><td><a href="./ome-tiff.html">OME-TIFF</a></td><td>Microscopy</td><td>One file</td><td>Images in 2D and 3D, with Z and T</td><td>Not needed</td></tr><tr><td><a href="./zeiss-czi.html">Zeiss CZI</a></td><td>Microscopy</td><td>One file, or a folder of one file per field</td><td>Images in 2D and 3D. Plates in Field view, and Well and Plate view up to 256 MB</td><td>Yes, one CZI per field</td></tr><tr><td><a href="./opera-phenix-plates.html">Opera Phenix / Harmony</a></td><td>Plates</td><td>The measurement folder</td><td>Field view, and Well and Plate view up to 256 MB</td><td>Yes, compressed or not</td></tr><tr><td><a href="./yokogawa-plates.html">Yokogawa CellVoyager</a></td><td>Plates</td><td>The measurement folder</td><td>Field view, and Well and Plate view up to 256 MB</td><td>Yes, compressed or not</td></tr><tr><td><a href="./aperio-svs.html">Aperio SVS</a></td><td>Pathology</td><td>One file</td><td>Slide in 2D</td><td>Not needed</td></tr><tr><td><a href="./hamamatsu-ndpi.html">Hamamatsu NDPI</a></td><td>Pathology</td><td>One file, also over 4 GB</td><td>Slide in 2D</td><td>Not needed</td></tr><tr><td><a href="./leica-scn.html">Leica SCN</a></td><td>Pathology</td><td>One file, every region</td><td>Slide in 2D</td><td>Not needed</td></tr><tr><td><a href="./philips-tiff.html">Philips TIFF</a></td><td>Pathology</td><td>One file</td><td>Slide in 2D</td><td>Not needed</td></tr><tr><td><a href="./akoya-qptiff.html">Akoya QPTIFF</a></td><td>Pathology</td><td>One file, or an inForm <code>.tif</code> export</td><td>Slide in 2D, brightfield or multiplex</td><td>Not needed</td></tr><tr><td><a href="./mrxs.html">3DHISTECH MRXS</a></td><td>Pathology</td><td>The <code>.mrxs</code> file with its folder</td><td>Slide in 2D</td><td>Yes</td></tr><tr><td><a href="./dicom-wsi.html">DICOM WSI</a></td><td>Pathology</td><td>A folder of <code>.dcm</code> files</td><td>Slide in 2D</td><td>Yes</td></tr></tbody></table><p>Each opens from your disk, and most by their address too. A DICOM folder and a CZI plate saved as one file per field open by address as a zip. A zip made without compression is one file, so it opens in every browser, from your disk or its address. Which plate views each format gets: <a href="#plates-at-a-glance">Plates at a glance</a>. Details and limits are on each format&#39;s page. Which formats state their pixel size and magnification, and how to set them when a file does not: <a href="./calibration.html">Pixel Size and Magnification</a>.</p><h2 id="plates-at-a-glance" tabindex="-1">Plates at a glance <a class="header-anchor" href="#plates-at-a-glance" aria-label="Permalink to &quot;Plates at a glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Format</th><th>Plate view</th><th>Well view</th><th>Z planes</th><th>Timepoints</th><th>3D</th><th>Labels in the plate</th><th>Limits</th></tr></thead><tbody><tr><td><a href="./hcs-plates.html">OME-Zarr</a></td><td>Yes</td><td>Yes</td><td>All</td><td>All</td><td>Yes, field by field</td><td>Yes</td><td><a href="./hcs-plates.html#view-modes">View modes</a></td></tr><tr><td><a href="./zeiss-czi.html#plates">Zeiss CZI</a>, one file</td><td>Up to 256 MB</td><td>Up to 256 MB</td><td>All</td><td>All</td><td>Yes, when a field has Z planes</td><td>No</td><td><a href="./zeiss-czi.html#if-a-file-does-not-open">If a file does not open</a></td></tr><tr><td><a href="./zeiss-czi.html#plates-saved-as-one-file-per-field">Zeiss CZI</a>, one file per field</td><td>Up to 256 MB</td><td>Up to 256 MB</td><td>All</td><td>All</td><td>Yes, when a field has Z planes</td><td>No</td><td><a href="./zeiss-czi.html#plates-saved-as-one-file-per-field">One file per field</a></td></tr><tr><td><a href="./opera-phenix-plates.html">Opera Phenix / Harmony</a></td><td>Up to 256 MB</td><td>Up to 256 MB</td><td>All</td><td>All</td><td>Yes, when a field has Z planes</td><td>No</td><td><a href="./opera-phenix-plates.html#limits">Limits</a></td></tr><tr><td><a href="./yokogawa-plates.html">Yokogawa CellVoyager</a></td><td>Up to 256 MB</td><td>Up to 256 MB</td><td>Plane 1</td><td>All</td><td>No</td><td>No</td><td><a href="./yokogawa-plates.html#limits">Limits</a></td></tr></tbody></table><p>Every plate opens in Field view, with the well navigator and the well picker. Plate view shows one field per well, and Well view every field of one well. OME-Zarr stores each field at lower resolutions too, so both views work at any plate size. CZI, Opera Phenix and Yokogawa plates keep each field at one resolution, so a view opens when its full-size images fit in 256 MB. A small CZI plate gets all three views; on a 384-well JUMP plate, Well view is on and Plate view is off. <a href="./opera-phenix-plates.html#why-there-is-no-plate-or-well-view">Plate and Well view</a> explains it. <a href="https://www.find-nuclei.com/blog/how-to-convert-to-ome-zarr" target="_blank" rel="noreferrer">Convert a plate to OME-Zarr</a> for Plate view at any size.</p><h2 id="slides-at-a-glance" tabindex="-1">Slides at a glance <a class="header-anchor" href="#slides-at-a-glance" aria-label="Permalink to &quot;Slides at a glance&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Format</th><th>Compression</th><th>Label and macro</th><th>Colour profile (ICC)</th><th>Over 4 GB</th><th>Several regions or planes</th><th>Fluorescence</th><th>Limits</th></tr></thead><tbody><tr><td><a href="./aperio-svs.html">Aperio SVS</a></td><td>JPEG, JPEG 2000</td><td>Both</td><td>Yes</td><td>Not yet</td><td>One image</td><td>No, 8-bit RGB</td><td><a href="./aperio-svs.html#if-a-slide-does-not-open">If a slide does not open</a></td></tr><tr><td><a href="./hamamatsu-ndpi.html">Hamamatsu NDPI</a></td><td>JPEG</td><td>Macro</td><td>Yes</td><td>Yes</td><td>The plane at focus 0, with a note</td><td>Not yet</td><td><a href="./hamamatsu-ndpi.html#if-a-slide-does-not-open">If a slide does not open</a></td></tr><tr><td><a href="./leica-scn.html">Leica SCN</a></td><td>JPEG</td><td>Macro, brightfield and fluorescence</td><td>Yes</td><td>Yes</td><td>Every region, each as its own image. Z: the first plane</td><td>Yes</td><td><a href="./leica-scn.html#if-a-slide-does-not-open">If a slide does not open</a></td></tr><tr><td><a href="./philips-tiff.html">Philips TIFF</a></td><td>JPEG</td><td>Both</td><td>Yes</td><td>Yes</td><td>One image</td><td>No, 8-bit RGB</td><td><a href="./philips-tiff.html#if-a-slide-does-not-open">If a slide does not open</a></td></tr><tr><td><a href="./akoya-qptiff.html">Akoya QPTIFF</a></td><td>None, LZW, JPEG, Deflate</td><td>Not shown, with a note</td><td>No</td><td>Yes</td><td>One image</td><td>Yes, multiplex up to 32-bit</td><td><a href="./akoya-qptiff.html#if-a-slide-does-not-open">If a slide does not open</a></td></tr><tr><td><a href="./mrxs.html">3DHISTECH MRXS</a></td><td>JPEG, PNG, BMP</td><td>Both</td><td>No</td><td>Not tested yet</td><td>One slide</td><td>Yes, its filter channels</td><td><a href="./mrxs.html#if-a-slide-does-not-open">If a slide does not open</a></td></tr><tr><td><a href="./dicom-wsi.html">DICOM WSI</a></td><td>None, JPEG, JPEG 2000</td><td>Both</td><td>Yes</td><td>Yes</td><td>The largest slide, with a note. Z: the first plane</td><td>No, 8-bit RGB</td><td><a href="./dicom-wsi.html#if-a-slide-does-not-open">If a slide does not open</a></td></tr></tbody></table><p>Every slide opens as a pyramid. A level the file does not store is made from the one above it, so zoom stays smooth. The label and macro show as thumbnails under the title; click one to enlarge it. A label may show patient details: the viewer shows it and never saves or sends it. The colour profile can be turned off in the side panel.</p><p>Annotations open with any slide from GeoJSON or OME-XML, and from the scanner&#39;s own files: Aperio ImageScope XML, Hamamatsu NDP.view <code>.ndpa</code> and ASAP XML. See <a href="./annotation-exchange.html">Exchanging Annotations</a>.</p><h2 id="companion-data" tabindex="-1">Companion data <a class="header-anchor" href="#companion-data" aria-label="Permalink to &quot;Companion data&quot;">​</a></h2><ul><li><strong>Label masks</strong> that live outside the image: a Zarr label array from a URL, or from a folder in Chrome and Edge. See <a href="./labels.html">Labels</a>.</li><li><strong>Measurements and analysis bundles:</strong> a CSV or Parquet table with one row per object, up to a run manifest that lists several masks and tables, all from one URL. A table also opens from your disk in Chrome and Edge. See <a href="./analytics-format.html">Analytics Data Format</a>, and <a href="https://www.find-nuclei.com/blog/hcs-analytics-in-the-browser" target="_blank" rel="noreferrer">HCS Analytics in the Browser</a> for a real screen.</li><li><strong>Plate manifests:</strong> a small JSON file that describes an Opera Phenix or Yokogawa CellVoyager plate. Save one from the viewer and open it by URL. The format is a published JSON Schema: <a href="https://find-nuclei.github.io/schemas/plate-manifest/v1.json" target="_blank" rel="noreferrer">plate-manifest/v1.json</a>.</li></ul><h2 id="which-browser-opens-what" tabindex="-1">Which browser opens what <a class="header-anchor" href="#which-browser-opens-what" aria-label="Permalink to &quot;Which browser opens what&quot;">​</a></h2><p>One file and every address open in every browser. A folder from your disk needs Chrome or Edge. The full table is in <a href="./local-files.html#which-browsers-can-do-this">Local Files</a>.</p><h2 id="not-supported-yet" tabindex="-1">Not supported yet <a class="header-anchor" href="#not-supported-yet" aria-label="Permalink to &quot;Not supported yet&quot;">​</a></h2><p>Other vendor formats open after conversion to OME-Zarr. <a href="https://www.find-nuclei.com/blog/how-to-convert-to-ome-zarr" target="_blank" rel="noreferrer">How to Convert Any Microscopy File to OME-Zarr</a> shows how.</p><p>Which format should we add next? Tell us at <a href="mailto:info@find-nuclei.com" target="_blank" rel="noreferrer">info@find-nuclei.com</a>.</p>',18)])])}const c=e(r,[["render",i]]);export{m as __pageData,c as default};
